-- Idempotent; vorhandene IDs, Konten, Fortschritte, XP und Freischaltungen bleiben erhalten.
DO $v51_seed$
DECLARE r record; lesson text; category text; level text; min_plan text; plan text; lang text; kapitel text; payload jsonb;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset($data_v51$[{"course":"blender-fundamentals","ordinal":1,"title":"3D-Cursor positionieren","theory":"Der 3D-Cursor markiert eine Position im Raum und dient unter anderem als Einfügeort für neue Objekte. Im Viewport kannst du ihn gezielt setzen.","example":"Shift + Rechtsklick verschiebt den 3D-Cursor in der üblichen Standard-Tastenbelegung.","example_note":"Wenn ein Würfel am Cursor eingefügt wird, entsteht er an der markierten Stelle.","task":"Setze den Cursor auf den Ursprung und füge einen Würfel ein.","q1":{"question":"Welche Aussage erklärt „3D-Cursor positionieren“ richtig?","options":["Der Origin ist der Bezugspunkt für Objekt-Transformationen und wichtige Modifikatoren. Er muss nicht auf der sichtbaren Geometrie liegen.","Der 3D-Cursor markiert eine Position im Raum und dient unter anderem als Einfügeort für neue Objekte. Im Viewport kannst du ihn gezielt setzen.","Normals bestimmen die Orientierung von Flächen und beeinflussen Beleuchtung und Export. Falsch ausgerichtete Flächen können verschwinden oder falsch schattiert wirken."],"correct":1,"explanation":"Der 3D-Cursor markiert eine Position im Raum und dient unter anderem als Einfügeort für neue Objekte. Im Viewport kannst du ihn gezielt setzen."},"q2":{"question":"Was zeigt das Beispiel zu „3D-Cursor positionieren“?","options":["Der Ursprung wird an die Geometrie verlegt; die Position der sichtbaren Form kann dabei gleich bleiben.","Blau markiert normalerweise Vorderseiten und Rot Rückseiten bei dieser Ansicht.","Wenn ein Würfel am Cursor eingefügt wird, entsteht er an der markierten Stelle."],"correct":2,"explanation":"Wenn ein Würfel am Cursor eingefügt wird, entsteht er an der markierten Stelle."}},{"course":"blender-fundamentals","ordinal":2,"title":"Objektursprung verstehen","theory":"Der Origin ist der Bezugspunkt für Objekt-Transformationen und wichtige Modifikatoren. Er muss nicht auf der sichtbaren Geometrie liegen.","example":"Object > Set Origin > Origin to Geometry","example_note":"Der Ursprung wird an die Geometrie verlegt; die Position der sichtbaren Form kann dabei gleich bleiben.","task":"Versetze den Ursprung eines Würfels und vergleiche seine Rotation.","q1":{"question":"Welche Aussage erklärt „Objektursprung verstehen“ richtig?","options":["Objektskalierung und echte Mesh-Koordinaten sind unterschiedlich. Apply Scale überträgt die sichtbare Skalierung auf die Geometrie.","Der Subdivision-Surface-Modifikator unterteilt und glättet eine Mesh-Oberfläche. Stützkanten beeinflussen die Form an Ecken.","Der Origin ist der Bezugspunkt für Objekt-Transformationen und wichtige Modifikatoren. Er muss nicht auf der sichtbaren Geometrie liegen."],"correct":2,"explanation":"Der Origin ist der Bezugspunkt für Objekt-Transformationen und wichtige Modifikatoren. Er muss nicht auf der sichtbaren Geometrie liegen."},"q2":{"question":"Was zeigt das Beispiel zu „Objektursprung verstehen“?","options":["Der Ursprung wird an die Geometrie verlegt; die Position der sichtbaren Form kann dabei gleich bleiben.","Nach dem Anwenden stehen die Skalierungswerte wieder auf 1, obwohl das Modell seine Größe beibehält.","Ein einfacher Würfel wird ohne zusätzliche Stützkanten deutlich abgerundet."],"correct":0,"explanation":"Der Ursprung wird an die Geometrie verlegt; die Position der sichtbaren Form kann dabei gleich bleiben."}},{"course":"blender-fundamentals","ordinal":3,"title":"Skalierung anwenden","theory":"Objektskalierung und echte Mesh-Koordinaten sind unterschiedlich. Apply Scale überträgt die sichtbare Skalierung auf die Geometrie.","example":"Object Mode > Ctrl+A > Scale","example_note":"Nach dem Anwenden stehen die Skalierungswerte wieder auf 1, obwohl das Modell seine Größe beibehält.","task":"Skaliere einen Würfel und wende anschließend Scale an.","q1":{"question":"Welche Aussage erklärt „Skalierung anwenden“ richtig?","options":["Objektskalierung und echte Mesh-Koordinaten sind unterschiedlich. Apply Scale überträgt die sichtbare Skalierung auf die Geometrie.","Normals bestimmen die Orientierung von Flächen und beeinflussen Beleuchtung und Export. Falsch ausgerichtete Flächen können verschwinden oder falsch schattiert wirken.","Eine UV-Map bildet 3D-Oberflächen auf 2D-Koordinaten ab, damit Texturen richtig platziert werden. Seams legen Schnittkanten fest."],"correct":0,"explanation":"Objektskalierung und echte Mesh-Koordinaten sind unterschiedlich. Apply Scale überträgt die sichtbare Skalierung auf die Geometrie."},"q2":{"question":"Was zeigt das Beispiel zu „Skalierung anwenden“?","options":["Blau markiert normalerweise Vorderseiten und Rot Rückseiten bei dieser Ansicht.","Nach dem Anwenden stehen die Skalierungswerte wieder auf 1, obwohl das Modell seine Größe beibehält.","Das Objekt erhält abwickelbare UV-Inseln, die im UV-Editor sichtbar sind."],"correct":1,"explanation":"Nach dem Anwenden stehen die Skalierungswerte wieder auf 1, obwohl das Modell seine Größe beibehält."}},{"course":"blender-fundamentals","ordinal":4,"title":"Normals anzeigen","theory":"Normals bestimmen die Orientierung von Flächen und beeinflussen Beleuchtung und Export. Falsch ausgerichtete Flächen können verschwinden oder falsch schattiert wirken.","example":"Edit Mode > Overlays > Face Orientation","example_note":"Blau markiert normalerweise Vorderseiten und Rot Rückseiten bei dieser Ansicht.","task":"Prüfe die Flächenausrichtung eines Würfels.","q1":{"question":"Welche Aussage erklärt „Normals anzeigen“ richtig?","options":["Der Subdivision-Surface-Modifikator unterteilt und glättet eine Mesh-Oberfläche. Stützkanten beeinflussen die Form an Ecken.","Normals bestimmen die Orientierung von Flächen und beeinflussen Beleuchtung und Export. Falsch ausgerichtete Flächen können verschwinden oder falsch schattiert wirken.","Der 3D-Cursor markiert eine Position im Raum und dient unter anderem als Einfügeort für neue Objekte. Im Viewport kannst du ihn gezielt setzen."],"correct":1,"explanation":"Normals bestimmen die Orientierung von Flächen und beeinflussen Beleuchtung und Export. Falsch ausgerichtete Flächen können verschwinden oder falsch schattiert wirken."},"q2":{"question":"Was zeigt das Beispiel zu „Normals anzeigen“?","options":["Ein einfacher Würfel wird ohne zusätzliche Stützkanten deutlich abgerundet.","Wenn ein Würfel am Cursor eingefügt wird, entsteht er an der markierten Stelle.","Blau markiert normalerweise Vorderseiten und Rot Rückseiten bei dieser Ansicht."],"correct":2,"explanation":"Blau markiert normalerweise Vorderseiten und Rot Rückseiten bei dieser Ansicht."}},{"course":"blender-fundamentals","ordinal":5,"title":"Subdivision Surface","theory":"Der Subdivision-Surface-Modifikator unterteilt und glättet eine Mesh-Oberfläche. Stützkanten beeinflussen die Form an Ecken.","example":"Modifiers > Add Modifier > Subdivision Surface","example_note":"Ein einfacher Würfel wird ohne zusätzliche Stützkanten deutlich abgerundet.","task":"Erstelle eine runde Form mit Subdivision und einer Stützkante.","q1":{"question":"Welche Aussage erklärt „Subdivision Surface“ richtig?","options":["Eine UV-Map bildet 3D-Oberflächen auf 2D-Koordinaten ab, damit Texturen richtig platziert werden. Seams legen Schnittkanten fest.","Der Origin ist der Bezugspunkt für Objekt-Transformationen und wichtige Modifikatoren. Er muss nicht auf der sichtbaren Geometrie liegen.","Der Subdivision-Surface-Modifikator unterteilt und glättet eine Mesh-Oberfläche. Stützkanten beeinflussen die Form an Ecken."],"correct":2,"explanation":"Der Subdivision-Surface-Modifikator unterteilt und glättet eine Mesh-Oberfläche. Stützkanten beeinflussen die Form an Ecken."},"q2":{"question":"Was zeigt das Beispiel zu „Subdivision Surface“?","options":["Ein einfacher Würfel wird ohne zusätzliche Stützkanten deutlich abgerundet.","Das Objekt erhält abwickelbare UV-Inseln, die im UV-Editor sichtbar sind.","Der Ursprung wird an die Geometrie verlegt; die Position der sichtbaren Form kann dabei gleich bleiben."],"correct":0,"explanation":"Ein einfacher Würfel wird ohne zusätzliche Stützkanten deutlich abgerundet."}},{"course":"blender-fundamentals","ordinal":6,"title":"UV-Unwrapping","theory":"Eine UV-Map bildet 3D-Oberflächen auf 2D-Koordinaten ab, damit Texturen richtig platziert werden. Seams legen Schnittkanten fest.","example":"Edit Mode > Mark Seam > U > Unwrap","example_note":"Das Objekt erhält abwickelbare UV-Inseln, die im UV-Editor sichtbar sind.","task":"Wickle eine Kiste ab und kontrolliere die Inseln.","q1":{"question":"Welche Aussage erklärt „UV-Unwrapping“ richtig?","options":["Eine UV-Map bildet 3D-Oberflächen auf 2D-Koordinaten ab, damit Texturen richtig platziert werden. Seams legen Schnittkanten fest.","Der 3D-Cursor markiert eine Position im Raum und dient unter anderem als Einfügeort für neue Objekte. Im Viewport kannst du ihn gezielt setzen.","Objektskalierung und echte Mesh-Koordinaten sind unterschiedlich. Apply Scale überträgt die sichtbare Skalierung auf die Geometrie."],"correct":0,"explanation":"Eine UV-Map bildet 3D-Oberflächen auf 2D-Koordinaten ab, damit Texturen richtig platziert werden. Seams legen Schnittkanten fest."},"q2":{"question":"Was zeigt das Beispiel zu „UV-Unwrapping“?","options":["Wenn ein Würfel am Cursor eingefügt wird, entsteht er an der markierten Stelle.","Das Objekt erhält abwickelbare UV-Inseln, die im UV-Editor sichtbar sind.","Nach dem Anwenden stehen die Skalierungswerte wieder auf 1, obwohl das Modell seine Größe beibehält."],"correct":1,"explanation":"Das Objekt erhält abwickelbare UV-Inseln, die im UV-Editor sichtbar sind."}},{"course":"blender-animation","ordinal":1,"title":"Location-Keyframe","theory":"Ein Keyframe speichert die Position eines Objekts zu einem bestimmten Frame. Blender berechnet Zwischenpositionen zwischen zwei Keys.","example":"Frame 1: X=0 > I; Frame 60: X=5 > I","example_note":"Beim Abspielen bewegt sich das Objekt von X=0 zu X=5, wenn beide Keyframes gesetzt wurden.","task":"Animier einen Würfel über 60 Frames nur auf X.","q1":{"question":"Welche Aussage erklärt „Location-Keyframe“ richtig?","options":["Rotations-Keyframes speichern die Orientierung eines Objekts zu verschiedenen Frames. Die Interpolation legt die Bewegung zwischen ihnen fest.","Ein Keyframe speichert die Position eines Objekts zu einem bestimmten Frame. Blender berechnet Zwischenpositionen zwischen zwei Keys.","Motion Blur simuliert Bewegungsunschärfe während einer Belichtung. Die Stärke hängt von Renderengine und Einstellungen ab."],"correct":1,"explanation":"Ein Keyframe speichert die Position eines Objekts zu einem bestimmten Frame. Blender berechnet Zwischenpositionen zwischen zwei Keys."},"q2":{"question":"Was zeigt das Beispiel zu „Location-Keyframe“?","options":["Der Würfel dreht sich zwischen den beiden Frames, statt sofort zu springen.","Schnell bewegte Objekte können entlang ihres Bewegungswegs unschärfer erscheinen.","Beim Abspielen bewegt sich das Objekt von X=0 zu X=5, wenn beide Keyframes gesetzt wurden."],"correct":2,"explanation":"Beim Abspielen bewegt sich das Objekt von X=0 zu X=5, wenn beide Keyframes gesetzt wurden."}},{"course":"blender-animation","ordinal":2,"title":"Rotation-Keyframe","theory":"Rotations-Keyframes speichern die Orientierung eines Objekts zu verschiedenen Frames. Die Interpolation legt die Bewegung zwischen ihnen fest.","example":"Frame 1: Z Rotation 0°; Frame 48: Z Rotation 90°","example_note":"Der Würfel dreht sich zwischen den beiden Frames, statt sofort zu springen.","task":"Animier eine Vierteldrehung um Z.","q1":{"question":"Welche Aussage erklärt „Rotation-Keyframe“ richtig?","options":["Lineare Interpolation bewegt eine animierte Eigenschaft zwischen Keyframes mit konstanter Änderungsrate. Im Graph Editor kannst du sie einstellen.","Schärfentiefe steuert, welche Entfernungen zur Kamera scharf wirken. Kamerafokus und Blendenwert beeinflussen die Stärke.","Rotations-Keyframes speichern die Orientierung eines Objekts zu verschiedenen Frames. Die Interpolation legt die Bewegung zwischen ihnen fest."],"correct":2,"explanation":"Rotations-Keyframes speichern die Orientierung eines Objekts zu verschiedenen Frames. Die Interpolation legt die Bewegung zwischen ihnen fest."},"q2":{"question":"Was zeigt das Beispiel zu „Rotation-Keyframe“?","options":["Der Würfel dreht sich zwischen den beiden Frames, statt sofort zu springen.","Eine Position nimmt gleichmäßig zu; es gibt keine standardmäßige Bezier-Beschleunigung.","Das ausgewählte Fokusobjekt bleibt scharf, während entfernte Objekte unschärfer werden können."],"correct":0,"explanation":"Der Würfel dreht sich zwischen den beiden Frames, statt sofort zu springen."}},{"course":"blender-animation","ordinal":3,"title":"Interpolation Linear","theory":"Lineare Interpolation bewegt eine animierte Eigenschaft zwischen Keyframes mit konstanter Änderungsrate. Im Graph Editor kannst du sie einstellen.","example":"Graph Editor > Key > Interpolation Mode > Linear","example_note":"Eine Position nimmt gleichmäßig zu; es gibt keine standardmäßige Bezier-Beschleunigung.","task":"Vergleiche lineare und Bezier-Interpolation.","q1":{"question":"Welche Aussage erklärt „Interpolation Linear“ richtig?","options":["Lineare Interpolation bewegt eine animierte Eigenschaft zwischen Keyframes mit konstanter Änderungsrate. Im Graph Editor kannst du sie einstellen.","Motion Blur simuliert Bewegungsunschärfe während einer Belichtung. Die Stärke hängt von Renderengine und Einstellungen ab.","Eine Bildsequenz speichert jedes Animationsframe separat. Sie ist bei langen Renders oft robuster als ein direkt erzeugtes Video."],"correct":0,"explanation":"Lineare Interpolation bewegt eine animierte Eigenschaft zwischen Keyframes mit konstanter Änderungsrate. Im Graph Editor kannst du sie einstellen."},"q2":{"question":"Was zeigt das Beispiel zu „Interpolation Linear“?","options":["Schnell bewegte Objekte können entlang ihres Bewegungswegs unschärfer erscheinen.","Eine Position nimmt gleichmäßig zu; es gibt keine standardmäßige Bezier-Beschleunigung.","Es entsteht für jeden gerenderten Frame eine Bilddatei, die später zu einem Film zusammengefügt werden kann."],"correct":1,"explanation":"Eine Position nimmt gleichmäßig zu; es gibt keine standardmäßige Bezier-Beschleunigung."}},{"course":"blender-animation","ordinal":4,"title":"Motion Blur","theory":"Motion Blur simuliert Bewegungsunschärfe während einer Belichtung. Die Stärke hängt von Renderengine und Einstellungen ab.","example":"Render Properties > Motion Blur, sofern von der aktiven Engine unterstützt.","example_note":"Schnell bewegte Objekte können entlang ihres Bewegungswegs unschärfer erscheinen.","task":"Render eine drehende Form mit und ohne Bewegungsunschärfe.","q1":{"question":"Welche Aussage erklärt „Motion Blur“ richtig?","options":["Schärfentiefe steuert, welche Entfernungen zur Kamera scharf wirken. Kamerafokus und Blendenwert beeinflussen die Stärke.","Motion Blur simuliert Bewegungsunschärfe während einer Belichtung. Die Stärke hängt von Renderengine und Einstellungen ab.","Ein Keyframe speichert die Position eines Objekts zu einem bestimmten Frame. Blender berechnet Zwischenpositionen zwischen zwei Keys."],"correct":1,"explanation":"Motion Blur simuliert Bewegungsunschärfe während einer Belichtung. Die Stärke hängt von Renderengine und Einstellungen ab."},"q2":{"question":"Was zeigt das Beispiel zu „Motion Blur“?","options":["Das ausgewählte Fokusobjekt bleibt scharf, während entfernte Objekte unschärfer werden können.","Beim Abspielen bewegt sich das Objekt von X=0 zu X=5, wenn beide Keyframes gesetzt wurden.","Schnell bewegte Objekte können entlang ihres Bewegungswegs unschärfer erscheinen."],"correct":2,"explanation":"Schnell bewegte Objekte können entlang ihres Bewegungswegs unschärfer erscheinen."}},{"course":"blender-animation","ordinal":5,"title":"Depth of Field","theory":"Schärfentiefe steuert, welche Entfernungen zur Kamera scharf wirken. Kamerafokus und Blendenwert beeinflussen die Stärke.","example":"Camera Properties > Depth of Field > Focus Object","example_note":"Das ausgewählte Fokusobjekt bleibt scharf, während entfernte Objekte unschärfer werden können.","task":"Erstelle eine Szene mit scharfem Vordergrund und unscharfem Hintergrund.","q1":{"question":"Welche Aussage erklärt „Depth of Field“ richtig?","options":["Eine Bildsequenz speichert jedes Animationsframe separat. Sie ist bei langen Renders oft robuster als ein direkt erzeugtes Video.","Rotations-Keyframes speichern die Orientierung eines Objekts zu verschiedenen Frames. Die Interpolation legt die Bewegung zwischen ihnen fest.","Schärfentiefe steuert, welche Entfernungen zur Kamera scharf wirken. Kamerafokus und Blendenwert beeinflussen die Stärke."],"correct":2,"explanation":"Schärfentiefe steuert, welche Entfernungen zur Kamera scharf wirken. Kamerafokus und Blendenwert beeinflussen die Stärke."},"q2":{"question":"Was zeigt das Beispiel zu „Depth of Field“?","options":["Das ausgewählte Fokusobjekt bleibt scharf, während entfernte Objekte unschärfer werden können.","Es entsteht für jeden gerenderten Frame eine Bilddatei, die später zu einem Film zusammengefügt werden kann.","Der Würfel dreht sich zwischen den beiden Frames, statt sofort zu springen."],"correct":0,"explanation":"Das ausgewählte Fokusobjekt bleibt scharf, während entfernte Objekte unschärfer werden können."}},{"course":"blender-animation","ordinal":6,"title":"Renderausgabe als Sequenz","theory":"Eine Bildsequenz speichert jedes Animationsframe separat. Sie ist bei langen Renders oft robuster als ein direkt erzeugtes Video.","example":"Output Properties > PNG > Render Animation","example_note":"Es entsteht für jeden gerenderten Frame eine Bilddatei, die später zu einem Film zusammengefügt werden kann.","task":"Rendere zehn Frames als PNG-Sequenz.","q1":{"question":"Welche Aussage erklärt „Renderausgabe als Sequenz“ richtig?","options":["Eine Bildsequenz speichert jedes Animationsframe separat. Sie ist bei langen Renders oft robuster als ein direkt erzeugtes Video.","Ein Keyframe speichert die Position eines Objekts zu einem bestimmten Frame. Blender berechnet Zwischenpositionen zwischen zwei Keys.","Lineare Interpolation bewegt eine animierte Eigenschaft zwischen Keyframes mit konstanter Änderungsrate. Im Graph Editor kannst du sie einstellen."],"correct":0,"explanation":"Eine Bildsequenz speichert jedes Animationsframe separat. Sie ist bei langen Renders oft robuster als ein direkt erzeugtes Video."},"q2":{"question":"Was zeigt das Beispiel zu „Renderausgabe als Sequenz“?","options":["Beim Abspielen bewegt sich das Objekt von X=0 zu X=5, wenn beide Keyframes gesetzt wurden.","Es entsteht für jeden gerenderten Frame eine Bilddatei, die später zu einem Film zusammengefügt werden kann.","Eine Position nimmt gleichmäßig zu; es gibt keine standardmäßige Bezier-Beschleunigung."],"correct":1,"explanation":"Es entsteht für jeden gerenderten Frame eine Bilddatei, die später zu einem Film zusammengefügt werden kann."}},{"course":"blender-technical","ordinal":1,"title":"Geometry Nodes Attribute","theory":"Attribute können pro Punkt, Kante, Fläche oder Instanz unterschiedliche Werte speichern. Geometry Nodes verarbeitet sie als Felder in einem Kontext.","example":"Position > Separate XYZ > Math > Set Position","example_note":"Positionen werden ausgewertet und durch berechnete Werte verändert.","task":"Verschiebe Punkte abhängig von ihrer X-Koordinate.","q1":{"question":"Welche Aussage erklärt „Geometry Nodes Attribute“ richtig?","options":["Instance on Points platziert Kopien einer Geometrie auf Punkten einer anderen Geometrie. Das ist oft speichereffizienter als echte Duplikate.","Attribute können pro Punkt, Kante, Fläche oder Instanz unterschiedliche Werte speichern. Geometry Nodes verarbeitet sie als Felder in einem Kontext.","Store Named Attribute speichert ein Feld unter einem Namen; spätere Nodes können es auslesen. Der Datentyp und die Domain müssen passen."],"correct":1,"explanation":"Attribute können pro Punkt, Kante, Fläche oder Instanz unterschiedliche Werte speichern. Geometry Nodes verarbeitet sie als Felder in einem Kontext."},"q2":{"question":"Was zeigt das Beispiel zu „Geometry Nodes Attribute“?","options":["Ein Ausgangsobjekt erscheint an vielen erzeugten Punktpositionen.","Andere Nodes können das gespeicherte Attribut über den Namen lesen.","Positionen werden ausgewertet und durch berechnete Werte verändert."],"correct":2,"explanation":"Positionen werden ausgewertet und durch berechnete Werte verändert."}},{"course":"blender-technical","ordinal":2,"title":"Instance on Points","theory":"Instance on Points platziert Kopien einer Geometrie auf Punkten einer anderen Geometrie. Das ist oft speichereffizienter als echte Duplikate.","example":"Distribute Points on Faces > Instance on Points","example_note":"Ein Ausgangsobjekt erscheint an vielen erzeugten Punktpositionen.","task":"Verteile identische Steine auf einer Fläche.","q1":{"question":"Welche Aussage erklärt „Instance on Points“ richtig?","options":["Realize Instances wandelt Instanzen in tatsächlich auswertbare Geometrie um. Dadurch können weitere Nodes direkt an einzelnen Vertices arbeiten.","Unterschiedliche Normalen und Glättungseinstellungen beeinflussen die Schattenwirkung einer exportierten Geometrie. Vor Export muss das Zielsystem geprüft werden.","Instance on Points platziert Kopien einer Geometrie auf Punkten einer anderen Geometrie. Das ist oft speichereffizienter als echte Duplikate."],"correct":2,"explanation":"Instance on Points platziert Kopien einer Geometrie auf Punkten einer anderen Geometrie. Das ist oft speichereffizienter als echte Duplikate."},"q2":{"question":"Was zeigt das Beispiel zu „Instance on Points“?","options":["Ein Ausgangsobjekt erscheint an vielen erzeugten Punktpositionen.","Nach Realize Instances liegen die Punkte als normale Geometrie für nachfolgende Operationen vor.","Falsch orientierte Flächen können im Zielprogramm unerwartet aussehen."],"correct":0,"explanation":"Ein Ausgangsobjekt erscheint an vielen erzeugten Punktpositionen."}},{"course":"blender-technical","ordinal":3,"title":"Realize Instances","theory":"Realize Instances wandelt Instanzen in tatsächlich auswertbare Geometrie um. Dadurch können weitere Nodes direkt an einzelnen Vertices arbeiten.","example":"Instance on Points > Realize Instances > Set Position","example_note":"Nach Realize Instances liegen die Punkte als normale Geometrie für nachfolgende Operationen vor.","task":"Vergleiche Performance und Mesh-Ausgabe vor und nach Realize.","q1":{"question":"Welche Aussage erklärt „Realize Instances“ richtig?","options":["Realize Instances wandelt Instanzen in tatsächlich auswertbare Geometrie um. Dadurch können weitere Nodes direkt an einzelnen Vertices arbeiten.","Store Named Attribute speichert ein Feld unter einem Namen; spätere Nodes können es auslesen. Der Datentyp und die Domain müssen passen.","Blenders bpy-API kann Szenenobjekte erzeugen und verändern. Manche Operatoren benötigen einen passenden Kontext."],"correct":0,"explanation":"Realize Instances wandelt Instanzen in tatsächlich auswertbare Geometrie um. Dadurch können weitere Nodes direkt an einzelnen Vertices arbeiten."},"q2":{"question":"Was zeigt das Beispiel zu „Realize Instances“?","options":["Andere Nodes können das gespeicherte Attribut über den Namen lesen.","Nach Realize Instances liegen die Punkte als normale Geometrie für nachfolgende Operationen vor.","Der Operator legt einen Würfel in der aktuellen Szene an."],"correct":1,"explanation":"Nach Realize Instances liegen die Punkte als normale Geometrie für nachfolgende Operationen vor."}},{"course":"blender-technical","ordinal":4,"title":"Named Attributes","theory":"Store Named Attribute speichert ein Feld unter einem Namen; spätere Nodes können es auslesen. Der Datentyp und die Domain müssen passen.","example":"Store Named Attribute mit Name \"gewicht\"","example_note":"Andere Nodes können das gespeicherte Attribut über den Namen lesen.","task":"Speichere ein Gewichtsfeld und verwende es für die Skalierung.","q1":{"question":"Welche Aussage erklärt „Named Attributes“ richtig?","options":["Unterschiedliche Normalen und Glättungseinstellungen beeinflussen die Schattenwirkung einer exportierten Geometrie. Vor Export muss das Zielsystem geprüft werden.","Store Named Attribute speichert ein Feld unter einem Namen; spätere Nodes können es auslesen. Der Datentyp und die Domain müssen passen.","Attribute können pro Punkt, Kante, Fläche oder Instanz unterschiedliche Werte speichern. Geometry Nodes verarbeitet sie als Felder in einem Kontext."],"correct":1,"explanation":"Store Named Attribute speichert ein Feld unter einem Namen; spätere Nodes können es auslesen. Der Datentyp und die Domain müssen passen."},"q2":{"question":"Was zeigt das Beispiel zu „Named Attributes“?","options":["Falsch orientierte Flächen können im Zielprogramm unerwartet aussehen.","Positionen werden ausgewertet und durch berechnete Werte verändert.","Andere Nodes können das gespeicherte Attribut über den Namen lesen."],"correct":2,"explanation":"Andere Nodes können das gespeicherte Attribut über den Namen lesen."}},{"course":"blender-technical","ordinal":5,"title":"Normals im Export","theory":"Unterschiedliche Normalen und Glättungseinstellungen beeinflussen die Schattenwirkung einer exportierten Geometrie. Vor Export muss das Zielsystem geprüft werden.","example":"Edit Mode > Mesh > Normals prüfen > Export","example_note":"Falsch orientierte Flächen können im Zielprogramm unerwartet aussehen.","task":"Untersuche und korrigiere einen absichtlich umgedrehten Face.","q1":{"question":"Welche Aussage erklärt „Normals im Export“ richtig?","options":["Blenders bpy-API kann Szenenobjekte erzeugen und verändern. Manche Operatoren benötigen einen passenden Kontext.","Instance on Points platziert Kopien einer Geometrie auf Punkten einer anderen Geometrie. Das ist oft speichereffizienter als echte Duplikate.","Unterschiedliche Normalen und Glättungseinstellungen beeinflussen die Schattenwirkung einer exportierten Geometrie. Vor Export muss das Zielsystem geprüft werden."],"correct":2,"explanation":"Unterschiedliche Normalen und Glättungseinstellungen beeinflussen die Schattenwirkung einer exportierten Geometrie. Vor Export muss das Zielsystem geprüft werden."},"q2":{"question":"Was zeigt das Beispiel zu „Normals im Export“?","options":["Falsch orientierte Flächen können im Zielprogramm unerwartet aussehen.","Der Operator legt einen Würfel in der aktuellen Szene an.","Ein Ausgangsobjekt erscheint an vielen erzeugten Punktpositionen."],"correct":0,"explanation":"Falsch orientierte Flächen können im Zielprogramm unerwartet aussehen."}},{"course":"blender-technical","ordinal":6,"title":"Blender Python Objekte","theory":"Blenders bpy-API kann Szenenobjekte erzeugen und verändern. Manche Operatoren benötigen einen passenden Kontext.","example":"import bpy\nbpy.ops.mesh.primitive_cube_add()","example_note":"Der Operator legt einen Würfel in der aktuellen Szene an.","task":"Schreibe ein kleines Skript, das drei Würfel erzeugt.","q1":{"question":"Welche Aussage erklärt „Blender Python Objekte“ richtig?","options":["Blenders bpy-API kann Szenenobjekte erzeugen und verändern. Manche Operatoren benötigen einen passenden Kontext.","Attribute können pro Punkt, Kante, Fläche oder Instanz unterschiedliche Werte speichern. Geometry Nodes verarbeitet sie als Felder in einem Kontext.","Realize Instances wandelt Instanzen in tatsächlich auswertbare Geometrie um. Dadurch können weitere Nodes direkt an einzelnen Vertices arbeiten."],"correct":0,"explanation":"Blenders bpy-API kann Szenenobjekte erzeugen und verändern. Manche Operatoren benötigen einen passenden Kontext."},"q2":{"question":"Was zeigt das Beispiel zu „Blender Python Objekte“?","options":["Positionen werden ausgewertet und durch berechnete Werte verändert.","Der Operator legt einen Würfel in der aktuellen Szene an.","Nach Realize Instances liegen die Punkte als normale Geometrie für nachfolgende Operationen vor."],"correct":1,"explanation":"Der Operator legt einen Würfel in der aktuellen Szene an."}},{"course":"blender-fivem-assets","ordinal":1,"title":"Maßstab für Game Assets","theory":"Ein Spielasset benötigt nachvollziehbare Weltmaße, damit es neben Spielcharakteren und Fahrzeugen sinnvoll groß wirkt. Vor Export muss die Skalierung konsistent sein.","example":"Object Properties > Dimensions > Einheiten prüfen","example_note":"Eine Tür sollte in ihrer Zielwelt eine passende Höhe und Breite besitzen.","task":"Baue einen einfachen Türrahmen mit realistischen Maßen.","q1":{"question":"Welche Aussage erklärt „Maßstab für Game Assets“ richtig?","options":["Der Objektursprung steuert eine Drehachse. Bei beweglichen Türen gehört der Pivot an das Scharnier, nicht in die Flächenmitte.","Ein Spielasset benötigt nachvollziehbare Weltmaße, damit es neben Spielcharakteren und Fahrzeugen sinnvoll groß wirkt. Vor Export muss die Skalierung konsistent sein.","Eine Kollisionsform beschreibt physische Grenzen und muss nicht identisch mit jedem sichtbaren Detail sein. Zu aufwendige Collider kosten Leistung."],"correct":1,"explanation":"Ein Spielasset benötigt nachvollziehbare Weltmaße, damit es neben Spielcharakteren und Fahrzeugen sinnvoll groß wirkt. Vor Export muss die Skalierung konsistent sein."},"q2":{"question":"Was zeigt das Beispiel zu „Maßstab für Game Assets“?","options":["Eine Drehung öffnet die Tür um ihre Scharnierkante.","Spieler stoßen mit der vereinfachten Form zusammen, während das Detailmodell sichtbar bleibt.","Eine Tür sollte in ihrer Zielwelt eine passende Höhe und Breite besitzen."],"correct":2,"explanation":"Eine Tür sollte in ihrer Zielwelt eine passende Höhe und Breite besitzen."}},{"course":"blender-fivem-assets","ordinal":2,"title":"Pivot für Türen","theory":"Der Objektursprung steuert eine Drehachse. Bei beweglichen Türen gehört der Pivot an das Scharnier, nicht in die Flächenmitte.","example":"Set Origin > Origin to 3D Cursor am Scharnier","example_note":"Eine Drehung öffnet die Tür um ihre Scharnierkante.","task":"Stelle bei einem Türmodell den Drehpunkt passend ein.","q1":{"question":"Welche Aussage erklärt „Pivot für Türen“ richtig?","options":["Level of Detail verwendet verschieden komplexe Modelle abhängig von der Entfernung. Die vereinfachte Version muss eine erkennbare Silhouette behalten.","Ähnliche Texeldichte sorgt dafür, dass Texturen auf verschiedenen Flächen vergleichbar scharf wirken. UV-Inselgrößen müssen dazu passen.","Der Objektursprung steuert eine Drehachse. Bei beweglichen Türen gehört der Pivot an das Scharnier, nicht in die Flächenmitte."],"correct":2,"explanation":"Der Objektursprung steuert eine Drehachse. Bei beweglichen Türen gehört der Pivot an das Scharnier, nicht in die Flächenmitte."},"q2":{"question":"Was zeigt das Beispiel zu „Pivot für Türen“?","options":["Eine Drehung öffnet die Tür um ihre Scharnierkante.","In größerer Entfernung können weniger Polygone gerendert werden.","Eine kleine Schraube erhält nicht unverhältnismäßig viel Texturfläche gegenüber einer großen Wand."],"correct":0,"explanation":"Eine Drehung öffnet die Tür um ihre Scharnierkante."}},{"course":"blender-fivem-assets","ordinal":3,"title":"LOD0 und LOD1","theory":"Level of Detail verwendet verschieden komplexe Modelle abhängig von der Entfernung. Die vereinfachte Version muss eine erkennbare Silhouette behalten.","example":"LOD0: detaillierter Würfelverbund; LOD1: vereinfachte Form","example_note":"In größerer Entfernung können weniger Polygone gerendert werden.","task":"Erstelle eine vereinfachte Zweitversion eines Props.","q1":{"question":"Welche Aussage erklärt „LOD0 und LOD1“ richtig?","options":["Level of Detail verwendet verschieden komplexe Modelle abhängig von der Entfernung. Die vereinfachte Version muss eine erkennbare Silhouette behalten.","Eine Kollisionsform beschreibt physische Grenzen und muss nicht identisch mit jedem sichtbaren Detail sein. Zu aufwendige Collider kosten Leistung.","Ein Texture Atlas vereint Materialien oder Texturteile in einer Grafik. Dadurch können Materialwechsel und Draw Calls reduziert werden."],"correct":0,"explanation":"Level of Detail verwendet verschieden komplexe Modelle abhängig von der Entfernung. Die vereinfachte Version muss eine erkennbare Silhouette behalten."},"q2":{"question":"Was zeigt das Beispiel zu „LOD0 und LOD1“?","options":["Spieler stoßen mit der vereinfachten Form zusammen, während das Detailmodell sichtbar bleibt.","In größerer Entfernung können weniger Polygone gerendert werden.","Mehrere Modellteile lesen unterschiedliche UV-Bereiche derselben Grafik."],"correct":1,"explanation":"In größerer Entfernung können weniger Polygone gerendert werden."}},{"course":"blender-fivem-assets","ordinal":4,"title":"Collider getrennt planen","theory":"Eine Kollisionsform beschreibt physische Grenzen und muss nicht identisch mit jedem sichtbaren Detail sein. Zu aufwendige Collider kosten Leistung.","example":"Sichtbares Modell: komplex; Kollision: vereinfachter Quader","example_note":"Spieler stoßen mit der vereinfachten Form zusammen, während das Detailmodell sichtbar bleibt.","task":"Entwerfe einen einfachen Collider für einen Tisch.","q1":{"question":"Welche Aussage erklärt „Collider getrennt planen“ richtig?","options":["Ähnliche Texeldichte sorgt dafür, dass Texturen auf verschiedenen Flächen vergleichbar scharf wirken. UV-Inselgrößen müssen dazu passen.","Eine Kollisionsform beschreibt physische Grenzen und muss nicht identisch mit jedem sichtbaren Detail sein. Zu aufwendige Collider kosten Leistung.","Ein Spielasset benötigt nachvollziehbare Weltmaße, damit es neben Spielcharakteren und Fahrzeugen sinnvoll groß wirkt. Vor Export muss die Skalierung konsistent sein."],"correct":1,"explanation":"Eine Kollisionsform beschreibt physische Grenzen und muss nicht identisch mit jedem sichtbaren Detail sein. Zu aufwendige Collider kosten Leistung."},"q2":{"question":"Was zeigt das Bei