,"title":"pyproject.toml","theory":"pyproject.toml bündelt Projektmetadaten und Build-Konfigurationen in einem standardisierten Format.","example":"[project]\nname=\"academy-tools\"\nversion=\"1.0.0\"","example_note":"Die Datei beschreibt Name und Version eines Python-Projekts.","task":"Lege ein kleines pyproject an.","q1":{"question":"Welche Aussage erklärt „pyproject.toml“ richtig?","options":["Pydantic überprüft Daten gegen deklarierte Modelle und kann klare Fehlermeldungen für ungültige Felder erzeugen.","Lange Hintergrundarbeiten sollten außerhalb der direkten Antwort verarbeitet werden, damit HTTP-Anfragen nicht unnötig blockieren.","pyproject.toml bündelt Projektmetadaten und Build-Konfigurationen in einem standardisierten Format."],"correct":2,"explanation":"pyproject.toml bündelt Projektmetadaten und Build-Konfigurationen in einem standardisierten Format."},"q2":{"question":"Was zeigt das Beispiel zu „pyproject.toml“?","options":["Die Datei beschreibt Name und Version eines Python-Projekts.","Bei einer Modellinstanz werden Daten anhand der Felddefinition geprüft.","Die Aufgabe wird nach der API-Antwort ausgeführt; für dauerhafte Jobs eignet sich eine echte Queue."],"correct":0,"explanation":"Die Datei beschreibt Name und Version eines Python-Projekts."}},{"course":"python-pro-lab","ordinal":3,"title":"Pydantic Validation","theory":"Pydantic überprüft Daten gegen deklarierte Modelle und kann klare Fehlermeldungen für ungültige Felder erzeugen.","example":"class User(BaseModel):\n    name: str","example_note":"Bei einer Modellinstanz werden Daten anhand der Felddefinition geprüft.","task":"Definiere ein Modell mit Name und positiver Zahl.","q1":{"question":"Welche Aussage erklärt „Pydantic Validation“ richtig?","options":["Pydantic überprüft Daten gegen deklarierte Modelle und kann klare Fehlermeldungen für ungültige Felder erzeugen.","APIRouter organisiert zusammengehörige Endpunkte, ohne alle Routen in einer einzigen Datei zu sammeln.","Eine Transaktion hält zusammengehörige Änderungen konsistent. Tritt ein Fehler auf, werden alle Änderungen zurückgerollt."],"correct":0,"explanation":"Pydantic überprüft Daten gegen deklarierte Modelle und kann klare Fehlermeldungen für ungültige Felder erzeugen."},"q2":{"question":"Was zeigt das Beispiel zu „Pydantic Validation“?","options":["Die Routen des Routers erhalten einen gemeinsamen Präfix.","Bei einer Modellinstanz werden Daten anhand der Felddefinition geprüft.","Die Session verwaltet das Zusammenfassen und Bestätigen der Datenbankänderungen."],"correct":1,"explanation":"Bei einer Modellinstanz werden Daten anhand der Felddefinition geprüft."}},{"course":"python-pro-lab","ordinal":4,"title":"FastAPI Router","theory":"APIRouter organisiert zusammengehörige Endpunkte, ohne alle Routen in einer einzigen Datei zu sammeln.","example":"router=APIRouter(prefix=\"/courses\")","example_note":"Die Routen des Routers erhalten einen gemeinsamen Präfix.","task":"Trenne Kurs- und Profilendpunkte.","q1":{"question":"Welche Aussage erklärt „FastAPI Router“ richtig?","options":["Lange Hintergrundarbeiten sollten außerhalb der direkten Antwort verarbeitet werden, damit HTTP-Anfragen nicht unnötig blockieren.","APIRouter organisiert zusammengehörige Endpunkte, ohne alle Routen in einer einzigen Datei zu sammeln.","Eine virtuelle Python-Umgebung trennt Projektabhängigkeiten vom globalen Interpreter. Das verhindert Paketkonflikte zwischen Projekten."],"correct":1,"explanation":"APIRouter organisiert zusammengehörige Endpunkte, ohne alle Routen in einer einzigen Datei zu sammeln."},"q2":{"question":"Was zeigt das Beispiel zu „FastAPI Router“?","options":["Die Aufgabe wird nach der API-Antwort ausgeführt; für dauerhafte Jobs eignet sich eine echte Queue.","Es entsteht ein eigener Installationsbereich für das Projekt.","Die Routen des Routers erhalten einen gemeinsamen Präfix."],"correct":2,"explanation":"Die Routen des Routers erhalten einen gemeinsamen Präfix."}},{"course":"python-pro-lab","ordinal":5,"title":"Background Tasks","theory":"Lange Hintergrundarbeiten sollten außerhalb der direkten Antwort verarbeitet werden, damit HTTP-Anfragen nicht unnötig blockieren.","example":"background_tasks.add_task(sende_mail,adresse)","example_note":"Die Aufgabe wird nach der API-Antwort ausgeführt; für dauerhafte Jobs eignet sich eine echte Queue.","task":"Unterscheide kurze Background Tasks und eine persistente Job-Queue.","q1":{"question":"Welche Aussage erklärt „Background Tasks“ richtig?","options":["Eine Transaktion hält zusammengehörige Änderungen konsistent. Tritt ein Fehler auf, werden alle Änderungen zurückgerollt.","pyproject.toml bündelt Projektmetadaten und Build-Konfigurationen in einem standardisierten Format.","Lange Hintergrundarbeiten sollten außerhalb der direkten Antwort verarbeitet werden, damit HTTP-Anfragen nicht unnötig blockieren."],"correct":2,"explanation":"Lange Hintergrundarbeiten sollten außerhalb der direkten Antwort verarbeitet werden, damit HTTP-Anfragen nicht unnötig blockieren."},"q2":{"question":"Was zeigt das Beispiel zu „Background Tasks“?","options":["Die Aufgabe wird nach der API-Antwort ausgeführt; für dauerhafte Jobs eignet sich eine echte Queue.","Die Session verwaltet das Zusammenfassen und Bestätigen der Datenbankänderungen.","Die Datei beschreibt Name und Version eines Python-Projekts."],"correct":0,"explanation":"Die Aufgabe wird nach der API-Antwort ausgeführt; für dauerhafte Jobs eignet sich eine echte Queue."}},{"course":"python-pro-lab","ordinal":6,"title":"Datenbanktransaktionen","theory":"Eine Transaktion hält zusammengehörige Änderungen konsistent. Tritt ein Fehler auf, werden alle Änderungen zurückgerollt.","example":"with session.begin():\n    session.add(order)","example_note":"Die Session verwaltet das Zusammenfassen und Bestätigen der Datenbankänderungen.","task":"Sichere zwei verbundene Datenänderungen in einer Transaktion.","q1":{"question":"Welche Aussage erklärt „Datenbanktransaktionen“ richtig?","options":["Eine Transaktion hält zusammengehörige Änderungen konsistent. Tritt ein Fehler auf, werden alle Änderungen zurückgerollt.","Eine virtuelle Python-Umgebung trennt Projektabhängigkeiten vom globalen Interpreter. Das verhindert Paketkonflikte zwischen Projekten.","Pydantic überprüft Daten gegen deklarierte Modelle und kann klare Fehlermeldungen für ungültige Felder erzeugen."],"correct":0,"explanation":"Eine Transaktion hält zusammengehörige Änderungen konsistent. Tritt ein Fehler auf, werden alle Änderungen zurückgerollt."},"q2":{"question":"Was zeigt das Beispiel zu „Datenbanktransaktionen“?","options":["Es entsteht ein eigener Installationsbereich für das Projekt.","Die Session verwaltet das Zusammenfassen und Bestätigen der Datenbankänderungen.","Bei einer Modellinstanz werden Daten anhand der Felddefinition geprüft."],"correct":1,"explanation":"Die Session verwaltet das Zusammenfassen und Bestätigen der Datenbankänderungen."}}]$data_v51$::jsonb)
 AS d(course text,ordinal integer,title text,theory text,example text,example_note text,task text,q1 jsonb,q2 jsonb)
 LOOP
  SELECT c.category,c.level INTO category,level FROM public.ll_courses c WHERE c.id=r.course;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown course: %',r.course; END IF;
  SELECT min(i.required_plan) INTO min_plan FROM public.ll_lesson_index i WHERE i.course_id=r.course;
  IF r.course='coding-basics' THEN plan:='free';
  ELSIF min_plan='free' AND r.ordinal<=2 THEN plan:='free';
  ELSIF min_plan='plus' AND r.ordinal<=2 THEN plan:='plus';
  ELSE plan:='pro'; END IF;
  lang:=CASE
    WHEN r.course LIKE 'blender-%' THEN 'blender'
    WHEN r.course IN('fivem','fivemadmin','nui','ox','qbcore','esx','security','lua-masterlab') THEN 'lua'
    WHEN r.course='coding-basics' THEN 'python'
    WHEN r.course IN('browsergames','webapps','fullstack-pro-lab','proskills','react','nodejs','api') THEN 'javascript'
    WHEN r.course='docker' THEN 'bash'
    ELSE r.course END;
  lesson:=r.course||'-path-'||lpad(r.ordinal::text,3,'0');
  kapitel:=CASE WHEN r.ordinal<=4 THEN 'Vertiefung I · Einzelschritte'
    WHEN r.ordinal<=8 THEN 'Vertiefung II · Fortgeschritten'
    WHEN r.ordinal<=12 THEN 'Vertiefung III · Profi-Werkzeuge'
    ELSE 'Vertiefung IV · Expertenwissen' END;
  INSERT INTO public.ll_lesson_index(id,course_id,chapter,position,title,summary,minutes,required_plan)
  VALUES(lesson,r.course,kapitel,7000+r.ordinal,r.title,left(r.theory,320),20,plan)
  ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,summary=EXCLUDED.summary,chapter=EXCLUDED.chapter,required_plan=EXCLUDED.required_plan;
  payload:=jsonb_build_object(
    'id',lesson,'title',r.title,'courseId',r.course,'category',category,'level',level,'duration',20,
    'goal','Du kannst '||r.title||' erklären und im Beispiel nachvollziehen.','theory',r.theory,
    'example',r.example,'example_notes',jsonb_build_array(r.example_note),
    'task',r.task,'hint',r.example_note,'lang',lang,'practice_mode','guided',
    'starter','','solution',r.example,'checks','[]'::jsonb,
    'quiz',r.q1->>'question','options',r.q1->'options','correct',(r.q1->>'correct')::integer,
    'quiz_items',jsonb_build_array(r.q1,r.q2),'quiz_version',3);
  INSERT INTO public.ll_lesson_content(lesson_id,payload,video_id,video_start)
  VALUES(lesson,payload,NULL,0)
  ON CONFLICT(lesson_id) DO UPDATE SET payload=EXCLUDED.payload;
 END LOOP;
END $v51_seed$;